//! 🫨️ Borrowed seismic site, building and parts-two-through-six entity cells before typed ownership.
use crate::sqlite::snapshot::*;
use store::sqlite_snapshot::artifact::RowWriter;
use semio_framework_dsl_record::RecordValue as R;
use semio_framework_value_native_owned::native_decoding::NativeDecodeControl;
use semio_s_artifact_norm_contract::sqlite_native as n;
use semio_s_artifact_norm_contract::sqlite_native::Column::*;
fn count(root:&R)->Result<usize,ValueError>{let mut rows=2;for id in 2..=22{rows=n::add(rows,n::list(n::field(root,id)?)?.len())?}for(id,nested)in[(2,4),(2,5),(2,6),(3,7),(9,7),(22,4),(22,5)]{for owner in n::list(n::field(root,id)?)?{rows=n::add(rows,n::list(n::field(n::record(owner)?,nested)?)?.len())?}}for owner in n::list(n::field(root,2)?)?{for storey in n::list(n::field(n::record(owner)?,5)?)?{rows=n::add(rows,n::list(n::field(n::record(storey)?,4)?)?.len())?}} Ok(rows)}
fn write(root:&R,out:&mut RowWriter<'_,'_>)->Result<(),ValueError>{
 out.insert_key_float("en1998_document",1,&n::cells(root,[Enumeration(0,&["En","De"])])?,&[])?;
 {let c=n::cells(n::record(n::field(root,1)?)?,[Real(0),Real(1),Enumeration(2,&["A-R","B-R","C-R","B-T","C-T","C-S"]),Enumeration(3,&["a","b","c","d","e"]),Enumeration(4,&["type1","type2"]),Enumeration(5,&["i","ii","iii","iv"]),Real(6),Real(7),Real(8),Real(9),Real(10),Boolean(11),Real(12),Real(13),Real(14)])?;out.insert_key_float("en1998_site",1,&[Cell::Integer(1),c[0],c[1],c[2],c[3],c[4],c[5],c[6],c[7],c[8],c[9],c[10],c[11],c[12],c[13],c[14]],SITE)?;}
 for(index,v)in n::list(n::field(root,2)?)?.iter().enumerate(){let v=n::record(v)?;let parent=n::entity(out,"en1998_building",1,index,&n::cells(v,[Text(0),Text(1),Real(2),Real(3),Boolean(7),Boolean(8),Enumeration(9,&["ct","rayleigh","given"]),Real(10),Real(11),Enumeration(12,&["brittle","ductile","isolated"]),Real(13),Boolean(14),Boolean(15),Real(16),Real(17),Real(18),Real(19),Real(20),Real(21),Real(22),Real(23),Real(24),Real(25),Real(26),Real(27),Real(28),Real(29),Real(30),Real(32),Enumeration(31,&["simplified","declared"])])?,BUILDING)?;for(index,a)in n::list(n::field(v,4)?)?.iter().enumerate(){n::entity(out,"en1998_system",parent,index,&n::cells(n::record(a)?,[Text(0),Enumeration(1,&["x","y"]),Enumeration(2,&["frame","wall","dual","masonry"]),Enumeration(3,&["rc","steel","composite","timber","masonry"]),Enumeration(4,&["dcl","dcm","dch"]),Real(5),Real(6),Real(7),Real(8)])?,SYSTEM)?;}for(index,a)in n::list(n::field(v,5)?)?.iter().enumerate(){let a=n::record(a)?;let storey=n::entity(out,"en1998_storey",parent,index,&n::cells(a,[Text(0),Real(1),Real(2),Boolean(3),Real(5),Real(6),Real(7),Real(8),Real(9),Real(10),Real(11),Real(12),Real(13)])?,STOREY)?;for(index,w)in n::list(n::field(a,4)?)?.iter().enumerate(){n::entity(out,"en1998_storey_variable",storey,index,&n::cells(n::record(w)?,[Text(0),Enumeration(1,&["a","b","c","d","e","f","g","h","snow","wind"]),Real(2)])?,VARIABLE)?;}}for(index,a)in n::list(n::field(v,6)?)?.iter().enumerate(){n::entity(out,"en1998_member",parent,index,&n::cells(n::record(a)?,[Text(0),Enumeration(1,&["rc","steel","composite","timber","masonry"]),Enumeration(2,&["beam","column","wall","brace"]),Boolean(3),Real(4),Real(5),Real(6),Real(7),Unsigned(8,u8::MAX as u64),Real(9),Real(10),Real(11),Real(12),Real(13),Real(14),Text(15),Real(16),Real(17),Real(18),Real(20),Enumeration(19,&["simplified","declared"])])?,MEMBER)?;}}
 for(index,v)in n::list(n::field(root,3)?)?.iter().enumerate(){let v=n::record(v)?;let parent=n::entity(out,"en1998_bridge",1,index,&n::cells(v,[Text(0),Real(1),Real(2),Real(3),Real(4),Real(5),Boolean(6),Real(8),Real(9),Real(10),Real(11),Real(12),Real(13),Real(14),Real(15)])?,BRIDGE)?;for(index,a)in n::list(n::field(v,7)?)?.iter().enumerate(){n::entity(out,"en1998_bridge_variable",parent,index,&n::cells(n::record(a)?,[Text(0),Enumeration(1,&["a","b","c","d","e","f","g","h","snow","wind"]),Real(2)])?,VARIABLE)?;}}
 for(index,v)in n::list(n::field(root,4)?)?.iter().enumerate(){n::entity(out,"en1998_assessment",1,index,&n::cells(n::record(v)?,[Text(0),Enumeration(1,&["kl1","kl2","kl3"]),Enumeration(2,&["nc","sd","dl"]),Text(3),Real(4),Real(5),Real(6),Real(7),Real(8),Real(9),Real(10),Real(11),Real(12),Real(13),Real(14),Real(15),Real(16),Real(17),Real(18),Real(19),Real(20),Real(21),Real(22),Real(23),Real(24),Real(25),Real(26),Real(27),Real(28),Real(29),Enumeration(30,&["derived","lf","mrs","pushover","nlth"])])?,ASSESSMENT)?;}
 for(index,v)in n::list(n::field(root,5)?)?.iter().enumerate(){n::entity(out,"en1998_silo",1,index,&n::cells(n::record(v)?,[Text(0),Real(1),Real(2),Real(3),Real(4),Enumeration(5,&["a","b","c","d","e","f","g","h","snow","wind"]),Real(6),Real(7),Real(8),Real(9)])?,SILO)?;}
 for(index,v)in n::list(n::field(root,6)?)?.iter().enumerate(){n::entity(out,"en1998_tank",1,index,&n::cells(n::record(v)?,[Text(0),Real(1),Real(2),Real(3),Real(4),Enumeration(5,&["a","b","c","d","e","f","g","h","snow","wind"]),Real(6),Real(7),Real(8),Real(9)])?,TANK)?;}
 for(index,v)in n::list(n::field(root,7)?)?.iter().enumerate(){n::entity(out,"en1998_foundation",1,index,&n::cells(n::record(v)?,[Text(0),Text(1),Real(2),Real(3),Real(4),Real(5),Real(6),Real(7),Real(8),Real(9),Real(10),Real(11),Real(12),Real(13),Real(14),Real(15),Real(16),Real(17),Real(18),Real(19),Real(20),Real(21),Real(22),Real(23),Real(24),Real(25),Real(26),Real(27),Real(28),Real(29),Real(30),Real(31),Real(32)])?,FOUNDATION)?;}
 for(index,v)in n::list(n::field(root,8)?)?.iter().enumerate(){n::entity(out,"en1998_retaining_wall",1,index,&n::cells(n::record(v)?,[Text(0),Real(1),Real(2),Real(3),Real(4),Real(5),Real(6),Real(7),Real(8)])?,WALL)?;}
 for(index,v)in n::list(n::field(root,9)?)?.iter().enumerate(){let v=n::record(v)?;let parent=n::entity(out,"en1998_tower",1,index,&n::cells(v,[Text(0),Real(1),Real(2),Boolean(3),Real(4),Real(5),Boolean(6),Real(8),Real(9)])?,TOWER)?;for(index,a)in n::list(n::field(v,7)?)?.iter().enumerate(){n::entity(out,"en1998_tower_variable",parent,index,&n::cells(n::record(a)?,[Text(0),Enumeration(1,&["a","b","c","d","e","f","g","h","snow","wind"]),Real(2)])?,VARIABLE)?;}}
 for(index,v)in n::list(n::field(root,16)?)?.iter().enumerate(){n::entity(out,"en1998_placement",1,index,&n::cells(n::record(v)?,[Text(0),Real(1),Real(2),Real(3),Real(4)])?,PLACEMENT)?;}
 for(index,v)in n::list(n::field(root,17)?)?.iter().enumerate(){n::entity(out,"en1998_tie_beam",1,index,&n::cells(n::record(v)?,[Text(0),Text(1),Text(2),Real(3),Real(4),Real(5),Real(6),Real(7),Real(8),Real(9)])?,TIE_BEAM)?;}
 for(index,v)in n::list(n::field(root,18)?)?.iter().enumerate(){n::entity(out,"en1998_slope",1,index,&n::cells(n::record(v)?,[Text(0),Text(1),Real(2),Real(3),Real(4),Real(5),Real(6),Real(7),Real(8),Real(9)])?,SLOPE)?;}
 for(index,v)in n::list(n::field(root,19)?)?.iter().enumerate(){n::entity(out,"en1998_isolation_system",1,index,&n::cells(n::record(v)?,[Text(0),Text(1),Text(2),Real(3),Real(4),Real(5),Real(6)])?,ISOLATION_SYSTEM)?;}
 for(index,v)in n::list(n::field(root,20)?)?.iter().enumerate(){n::entity(out,"en1998_pier_base",1,index,&n::cells(n::record(v)?,[Text(0),Text(1),Text(2),Real(3),Real(4),Real(5),Real(6)])?,PIER_BASE)?;}
 for(index,v)in n::list(n::field(root,21)?)?.iter().enumerate(){n::entity(out,"en1998_critical_region",1,index,&n::cells(n::record(v)?,[Text(0),Text(1),Text(2),Real(3),Real(4),Real(5),Real(6),Real(7),Real(8),Real(9),Real(10),Real(11),Real(12),Real(13),Real(14),Real(15),Real(16),Real(17),Real(18),Real(19),Real(20),Real(21)])?,CRITICAL_REGION)?;}
 for(index,v)in n::list(n::field(root,10)?)?.iter().enumerate(){n::entity(out,"en1998_soil_layer",1,index,&n::cells(n::record(v)?,[Text(0),Text(1),Real(2),Real(3),Real(4),Real(5),Real(6)])?,SOIL_LAYER)?;}
 for(index,v)in n::list(n::field(root,11)?)?.iter().enumerate(){n::entity(out,"en1998_diaphragm",1,index,&n::cells(n::record(v)?,[Text(0),Text(1),Text(2),Enumeration(3,&["concrete","timber","steelDeck"]),Real(4),Real(5),Real(6),Real(7),Real(8),Real(9),Real(10),Real(11)])?,DIAPHRAGM)?;}
 for(index,v)in n::list(n::field(root,12)?)?.iter().enumerate(){n::entity(out,"en1998_accelerogram",1,index,&n::cells(n::record(v)?,[Text(0),Text(1),Text(2),Text(3),Real(4),Real(5)])?,ACCELEROGRAM)?;}
 for(index,v)in n::list(n::field(root,13)?)?.iter().enumerate(){n::entity(out,"en1998_pier",1,index,&n::cells(n::record(v)?,[Text(0),Text(1),Real(2),Real(3),Real(4),Real(5),Real(6),Real(7),Real(8),Real(9),Real(10),Real(11),Real(12),Real(13),Enumeration(14,&["declared","computed"])])?,PIER)?;}
 for(index,v)in n::list(n::field(root,14)?)?.iter().enumerate(){n::entity(out,"en1998_bearing",1,index,&n::cells(n::record(v)?,[Text(0),Text(1),Text(2),Enumeration(3,&["fixed","elastomeric","sliding","isolator"]),Real(4),Real(5),Real(6),Real(7),Real(8)])?,BEARING)?;}
 for(index,v)in n::list(n::field(root,15)?)?.iter().enumerate(){n::entity(out,"en1998_joint",1,index,&n::cells(n::record(v)?,[Text(0),Text(1),Text(2),Text(3),Text(4),Real(5),Real(6),Real(7),Real(8)])?,JOINT)?;}
 for (index, row) in n::list(n::field(root, 22)?)?.iter().enumerate() {
     let row = n::record(row)?;
     let parent = n::entity(out, "en1998_case", 1, index, &n::cells(row, [Text(0), Text(1), Text(2), Text(3)])?, &[])?;
     for (index, number) in n::list(n::field(row, 4)?)?.iter().enumerate() {
         n::entity(out, "en1998_case_number", parent, index, &n::cells(n::record(number)?, [Text(0), Real(1)])?, CASE_NUMBER)?;
     }
     for (index, text) in n::list(n::field(row, 5)?)?.iter().enumerate() {
         n::entity(out, "en1998_case_text", parent, index, &n::cells(n::record(text)?, [Text(0), Text(1)])?, &[])?;
     }
 }
 Ok(())
}
/// 🛂️ Complete authored seismic tables and copied semantic controls.
pub fn admit(root:&R,native:&mut NativeDecodeControl<'_>,limits:store::sqlite_snapshot::SqliteDatabaseLimits)->Result<(),ValueError>{n::admit(root,native,limits,En1998Snapshot::SQLITE_SCHEMA,31,95,count(root)?,write)}
